// ===== Level Hunter — Auto-post REELS to Instagram + Facebook =====
// Config-оос: graphVersion, igUserId, pageId, accessToken, manifestUrl
//
// Carousel-ийн workflow-оос тусдаа: reel нь IG дээр media_type=REELS +
// video_url, FB дээр video_reels (эсвэл /videos) шаарддаг — өөр дуудлага.
const cfg = $input.first().json;
const G = `https://graph.facebook.com/${cfg.graphVersion}`;
const token = cfg.accessToken;
const igUser = cfg.igUserId;
const pageId = cfg.pageId;

const http = async (method, path, params) =>
  await this.helpers.httpRequest({
    method,
    url: `${G}/${path}`,
    qs: Object.assign({}, params, { access_token: token }),
    json: true,
  });

// 1) manifest татах
const manifest = await this.helpers.httpRequest({ method: 'GET', url: cfg.manifestUrl, json: true });

// 2) өнөөдрийн огноо (Asia/Ulaanbaatar = UTC+8)
const ub = new Date(Date.now() + 8 * 3600 * 1000);
const today = ub.toISOString().slice(0, 10);

// 3) өнөөдрийн queued reel
const post = (manifest.posts || []).find(p => p.date === today && p.status !== 'posted');
if (!post) {
  return [{ json: { skipped: true, today, reason: 'Өнөөдөр тавих reel алга' } }];
}

// Meta-д өгөх хаяг: jsDelivr нь content-type-аа video/mp4 гэж зөв өгдөг тул
// түүнийг эхэнд нь тавина; байхгүй бол raw хаяг руу шилжинэ.
const videoUrl = post.videoCdn || post.video;
if (!videoUrl) throw new Error('manifest дотор video хаяг алга: ' + post.id);

const out = { id: post.id, title: post.title, date: today, video: videoUrl, ig: null, fb: null };

// ---------- Instagram Reel (3 алхам) ----------
if (post.ig) {
  const container = await http('POST', `${igUser}/media`, {
    media_type: 'REELS',
    video_url: videoUrl,
    caption: post.caption,
    share_to_feed: true,
  });
  // Видео боловсруулалт зурагнаас удаан: 3 секунд тутам, 3 минут хүртэл хүлээнэ.
  let ready = false;
  for (let i = 0; i < 60; i++) {
    const s = await http('GET', `${container.id}`, { fields: 'status_code,status' });
    if (s.status_code === 'FINISHED') { ready = true; break; }
    if (s.status_code === 'ERROR') throw new Error('IG container ERROR: ' + JSON.stringify(s));
    await new Promise(r => setTimeout(r, 3000));
  }
  if (!ready) throw new Error('IG container 3 минутын дотор бэлэн болсонгүй: ' + container.id);
  const pub = await http('POST', `${igUser}/media_publish`, { creation_id: container.id });
  out.ig = pub.id;
}

// ---------- Facebook Reel ----------
// Эхлээд жинхэнэ FB Reel (video_reels, 3 фаз). Хэрэв энэ эрх/endpoint
// боломжгүй бол ердийн видео пост руу (/videos) шилжинэ — постлогдохгүй
// байснаас ердийн видео болж гарсан нь дээр.
if (post.fb) {
  try {
    const start = await http('POST', `${pageId}/video_reels`, { upload_phase: 'start' });
    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://rupload.facebook.com/video-upload/${cfg.graphVersion}/${start.video_id}`,
      headers: { Authorization: `OAuth ${token}`, file_url: videoUrl },
      json: true,
    });
    const finish = await http('POST', `${pageId}/video_reels`, {
      video_id: start.video_id,
      upload_phase: 'finish',
      video_state: 'PUBLISHED',
      description: post.caption,
    });
    out.fb = start.video_id;
    out.fbFinish = finish;
  } catch (error) {
    const vid = await http('POST', `${pageId}/videos`, {
      file_url: videoUrl,
      description: post.caption,
    });
    out.fb = vid.id;
    out.fbFallback = 'video_reels боломжгүй тул /videos-оор тавив: ' + (error.message || error);
  }
}

return [{ json: out }];
